async function load(){notice('불러오는 중…');const[tr,sn]=await Promise.all([supabase.from('transactions').select('*').order('traded_at',{ascending:false}),supabase.from('daily_snapshots').select('snapshot_date,total_equity,total_cost,cash_balance,holdings').order('snapshot_date',{ascending:true})]);if(tr.error||sn.error){notice(`데이터를 불러오지 못했습니다: ${(tr.error||sn.error).message}`,true);return}cache={rows:tr.data,snaps:sn.data};await loadQuotes(cache.rows);const saved=await saveTodaySnapshot(cache.rows,cache.snaps);if(saved)cache.snaps=[...cache.snaps.filter(s=>s.snapshot_date!==saved.snapshot_date),saved].sort((a,b)=>a.snapshot_date.localeCompare(b.snapshot_date));render(cache.rows,cache.snaps);notice('')}
function page(name){document.querySelectorAll('.page').forEach(e=>e.classList.toggle('active',e.id===`page-${name}`));document.querySelectorAll('.nav-item').forEach(e=>e.classList.toggle('active',e.dataset.page===name));window.scrollTo({top:0,behavior:'smooth'})}
