$('target-form').addEventListener('submit',e=>{e.preventDefault();const t=Object.fromEntries(Object.keys(defaults).map(k=>[k,+$(`target-${k.toLowerCase()}`).value])),sum=Object.values(t).reduce((a,b)=>a+b,0),m=$('target-message');if(Object.values(t).some(v=>!Number.isFinite(v)||v<0)||sum!==100){m.textContent=`합계가 정확히 100%여야 합니다. 현재 ${sum}%`;m.classList.add('error');return}localStorage.setItem('portfolio_target_allocations',JSON.stringify(t));m.textContent='이 기기에 목표 비중을 저장했습니다.';m.classList.remove('error');load()});
$('transaction-form').addEventListener('submit',async e=>{e.preventDefault();const type=$('trade-type').value,quantity=+$('quantity').value,price=+$('price').value,fee=+$('fee').value,isCash=['DEPOSIT','WITHDRAW'].includes(type);if((!isCash&&(!$('ticker').value.trim()||quantity<=0||price<=0))||(isCash&&price<=0)){notice('거래에 필요한 값이 모두 입력되었는지 확인하세요.',true);return}const r={user_id:'d5c24678-1079-48da-91f1-d7be47b9f975',traded_at:new Date($('traded-at').value).toISOString(),trade_type:type,ticker:isCash?'CASH':$('ticker').value.trim().toUpperCase(),quantity:isCash?0:quantity,price,amount:isCash?price:quantity*price,fee:isCash?0:fee,memo:$('memo').value.trim()}, {error}=await supabase.from('transactions').insert(r);if(error){notice(`저장하지 못했습니다: ${error.message}`,true);return}$('transaction-form').reset();$('traded-at').value=now();trade('BUY');notice('거래를 저장했습니다.');load()});
